def reason_text(code):
    return REASONS.get(code,'Сохранённых данных недостаточно для установления точной причины.')

def observations(check,result):
    return [result.get('evidence',{}).get(ref,{}).get('data',{}) for ref in check.get('evidence_refs',[])]

def explain(check,result):
    rule,outcome=check.get('rule_id'),check.get('outcome')
    if rule and rule.startswith('B'): return check.get('fact','Наблюдение браузера; подробности не сохранены.')
    if outcome=='pass': return PASS.get(rule,'В выполненной технической проверке дефект не обнаружен.')
    if outcome=='fail':
        finding=next((f for f in result['findings'] if f.get('rule_id')==rule and f.get('url')==check.get('url')),None)
        return finding.get('fact','Зафиксировано техническое замечание.') if finding else 'Зафиксировано техническое замечание; подробное описание в исходном отчёте отсутствует.'
    if outcome=='not_applicable':
        if rule in ('C03','C04','C05','C07'): return 'Правило применяется к явно обозначенным ссылкам на документы; данный объект проверялся как обычная страница.'
        if rule=='C02': return 'В полученных ответах нет HTTPS-соединения, к которому применима проверка сертификата.'
        if check.get('object_kind')=='document': return 'Этот объект проверялся как документ; правило предназначено для HTML-страниц.'
        if rule=='C06' and check.get('object_kind')=='page': return 'В исходной разметке не найдено подходящих для этого правила форм с полями e-mail, телефона или пароля (кроме диалоговых форм).'
        return 'Для правила не найден подходящий объект. В старом отчёте не сохранён контекст, позволяющий уточнить причину.'
    obs=observations(check,result)
    details=[]
    for i,o in enumerate(obs,1):
        if o.get('error'): value=reason_text(o['error'])
        elif o.get('ambiguous_html'): value='Разметка страницы неоднозначна; надёжно определить её структуру нельзя.'
        elif o.get('status'):
            status=o['status']; value=f'Ответ сервера: {status}.'
            value += {401:' Требуется авторизация.',403:' Доступ запрещён.',404:' Адрес не найден.',410:' Ресурс удалён.',429:' Слишком много запросов.'}.get(status,'')
            if status>=500: value+=' Ошибка на стороне сервера.'
            if o.get('content_type'):value+=' Тип ответа: '+str(o['content_type'])+'.'
        else: continue
        details.append(f'Попытка {i}: {value}')
    lead=reason_text(check.get('reason_code'))
    return lead+(' '+' '.join(details) if details else '')

FIELD_NAMES={'email':'Электронная почта','tel':'Телефон','password':'Пароль','text':'Текстовое поле','hidden':'Служебное скрытое поле','submit':'Кнопка отправки','checkbox':'Флажок выбора','radio':'Переключатель','textarea':'Многострочный текст','select':'Список выбора','button':'Кнопка','image':'Кнопка-изображение','other':'Другой тип'}
def esc(value):
    text=str(value)
    if '://' in text and 'sha256:' in text and len(text)<4096:
        text='Замаскированный идентификатор (не ссылка): '+text
    return html.escape(text,quote=True)
def table(headers,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def inventory_html(inv):
    out='<p>Ниже перечислены элементы, найденные в ответах сервера и исходной разметке. Их наличие не означает выполнение правового требования. Скрытые сценариями элементы могут не попасть в перечень. Часть адресов и имён замаскирована.</p>'
    out+='<h3>Документы и возможные ссылки на документы</h3>'
    rows=[[esc(d.get('label') or 'Возможный документ — назначение не подтверждено'),esc(d.get('url','')),esc(d.get('source','')), 'По явной подписи ссылки' if d.get('explicit') else 'По признаку в адресе; требуется уточнение'] for d in inv.get('documents',[])]
    out+=table(['Название','Адрес документа','Где найдена ссылка','Как определён'],rows) if rows else '<p>Подходящих ссылок в обследованной разметке не обнаружено. Это не доказывает отсутствие документов на сайте.</p>'
    out+='<h3>Формы на страницах</h3><p>Показаны типы элементов, а не введённые пользователями данные. Наличие флажка выбора не подтверждает получение согласия.</p>'
    rows=[]
    for f in inv.get('forms',[]):
        counts=Counter(FIELD_NAMES.get(x.get('type'),'Другой тип') for x in f.get('fields',[]))
        fields='; '.join(f'{k}: {v}' for k,v in counts.items()) or 'Поля не распознаны'
        action=esc(f.get('action')) if f.get('action') else 'Отдельный адрес в разметке не указан'
        if f.get('formaction'):action+='<br>Адреса отдельных кнопок: '+esc('; '.join(f['formaction']))
        rows.append([esc(f.get('page','')),esc(f"Форма {f.get('index',0)+1}"),esc(fields),action,'Не отправлялась'])
    out+=table(['Страница','Форма','Какие элементы найдены','Указанный адрес отправки','Действия сканера'],rows) if rows else '<p>Формы в обследованной исходной разметке не обнаружены. Динамические формы не проверялись.</p>'
    out+='<h3>Cookie, полученные от сервера</h3><p>Cookie — небольшие записи, которые сервер предлагает сохранить браузеру. Значения не сохраняются. Назначение (например, аналитика или вход) не определяется. Cookie, создаваемые JavaScript, не проверяются.</p>'
    rows=[]
    for c in inv.get('cookies',[]):
        age=c.get('max_age')
        if age is not None: lifetime=('Команда удалить запись' if age<=0 else f'Заданный срок: {age} секунд')
        elif c.get('expires'):lifetime='Указана дата окончания: '+str(c['expires'])
        elif c.get('expires_present'):lifetime='Дата окончания указана, но не распознана'
        else:lifetime='Срок не указан в полученном заголовке'
        flags='Только защищённое соединение: '+('да' if c.get('secure') else 'флаг не задан')+'; запрет чтения скриптами: '+('да' if c.get('httponly') else 'флаг не задан')
        flags+='; межсайтовая отправка: '+{'strict':'строго ограничена','lax':'частично ограничена','none':'атрибут допускает','unspecified':'атрибут не задан'}.get(c.get('samesite'),'не определена')
        rows.append([esc(c.get('name') or 'Имя не сохранено'),esc(c.get('source','')),esc(lifetime),esc(flags)])
    out+=table(['Имя или скрытый идентификатор','Источник','Срок','Атрибуты в ответе сервера'],rows) if rows else '<p>Cookie в обследованных ответах сервера не обнаружены. Это не означает, что сайт не использует cookie.</p>'
    out+='<h3>Другие сайты, упомянутые в разметке</h3><p>Это найденные адреса ссылок, ресурсов или форм. Упоминание домена не доказывает передачу ему персональных данных.</p>'
    rows=[[esc(x),'Найдено упоминание; фактическая передача данных не проверялась'] for x in inv.get('external_hosts',[])]
    out+=table(['Домен','Что известно'],rows) if rows else '<p>Внешние домены в обследованной разметке не обнаружены.</p>'
    return out
